function d_calibrate(P,R){var d=P.data||[];var n=d.length,sx=0,sy=0,sxx=0,sxy=0;for(var i=0;i<n;i++){sx+=d[i][0];sy+=d[i][1];sxx+=d[i][0]*d[i][0];sxy+=d[i][0]*d[i][1];}var slope=(n*sxy-sx*sy)/Math.max(1e-9,n*sxx-sx*sx),icept=(sy-slope*sx)/n;var ym=sy/n,ss=0,sr=0;for(i=0;i<n;i++){ss+=(d[i][1]-ym)*(d[i][1]-ym);var f=slope*d[i][0]+icept;sr+=(d[i][1]-f)*(d[i][1]-f);}return{slope:+slope.toFixed(5),intercept:+icept.toFixed(5),r_squared:+(1-sr/Math.max(1e-9,ss)).toFixed(5)};}

