function d_optimize(P,R){var f=P.f||'x^2';var lo=P.lo||-5,hi=P.hi||5,n=P.n||200,best={x:lo,v:1e18};for(var i=0;i<=n;i++){var x=lo+(hi-lo)*i/n,v;if(f==='rosenbrock'){var a=P.a||1,b=P.b||100;v=(a-x)*(a-x)+b*(0-x*x)*(0-x*x);}else v=x*x+(P.c||0)*x;if(v<best.v)best={x:+x.toFixed(4),v:+v.toFixed(6)};}return{function:f,best:best,evaluations:n+1};}

